program='''def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full horizontal bars encode a periodic sequence by row position.
    bars = []
    for r, row in enumerate(grid):
        vals = {v for v in row if v != 0}
        if vals:
            if len(vals) != 1 or len(row) != w or any(v == 0 for v in row):
                bars = None
                break
            bars.append((r, next(iter(vals))))
    if bars:
        for period in range(1, h + 1):
            seq = {}
            for r, color in bars:
                k = r % period
                if k in seq and seq[k] != color:
                    break
                seq[k] = color
            else:
                return [[seq[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal tracks encode the repeating color by the diagonal offset c-r.
    marks = [(c-r, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    for period in range(1, h + w + 1):
        seq = {}
        for offset, color in marks:
            k = offset % period
            if k in seq and seq[k] != color:
                break
            seq[k] = color
        else:
            return [[seq[(c-r) % period] for c in range(w)] for r in range(h)]
    raise ValueError("No consistent repeating pattern found")
'''
